 import React, { useState } from 'react'
import { useAuth } from '../../contexts/AuthContext'
import { useToast } from '../../contexts/ToastContext'
import { Link, useNavigate } from 'react-router-dom'
import { Eye, EyeOff } from 'lucide-react'
import { supabase } from '../../lib/supabase'

export default function Register() {
    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const [username, setUsername] = useState('')
    const [fullName, setFullName] = useState('')
    const [phone, setPhone] = useState('')
    const [error, setError] = useState('')
    const [loading, setLoading] = useState(false)
    const [showPassword, setShowPassword] = useState(false)
    const [passwordStrength, setPasswordStrength] = useState({ level: 0, text: '', color: '' })
    const { signUp } = useAuth()
    const { showToast } = useToast()
    const navigate = useNavigate()

    const checkPasswordStrength = (pass) => {
        let strength = 0
        if (pass.length >= 6) strength += 1
        if (pass.length >= 10) strength += 1
        if (/[a-z]/.test(pass) && /[A-Z]/.test(pass)) strength += 1
        if (/[0-9]/.test(pass)) strength += 1
        if (/[^a-zA-Z0-9]/.test(pass)) strength += 1
        
        const levels = ['Weak', 'Fair', 'Good', 'Strong', 'Very Strong']
        const colors = ['#ef4444', '#f59e0b', '#fbbf24', '#34d399', '#22c55e']
        const level = Math.min(strength, 4)
        
        setPasswordStrength({
            level: strength,
            text: pass ? levels[level] : '',
            color: pass ? colors[level] : '#e5e7eb'
        })
    }

    const handleSubmit = async (e) => {
        e.preventDefault()
        setError('')
        setLoading(true)

        // ✅ Normalize email
        const normalizedEmail = email.toLowerCase().trim()

        // Validate phone number (basic South African validation)
        const phoneRegex = /^(\+27|0)[6-8][0-9]{8}$/
        if (phone && !phoneRegex.test(phone)) {
            setError('Please enter a valid South African phone number (e.g., 0821234567 or +27821234567)')
            showToast('Invalid phone number', 'error')
            setLoading(false)
            return
        }

        try {
            // Optional: App-level check
            const { data: existing } = await supabase
                .from('profiles')
                .select('id')
                .eq('email', normalizedEmail)
                .maybeSingle()

            if (existing) {
                setError('An account with this email already exists. Please use a different email or log in.')
                showToast('Email already registered', 'error')
                setLoading(false)
                return
            }

            await signUp(normalizedEmail, password, username, fullName, phone)
            showToast('Account created successfully! Please check your email to confirm.', 'success')
            navigate('/login')
        } catch (err) {
            console.error('Sign up error:', err)

            // ✅ Clean duplicate key error handling
            if (err.message?.toLowerCase().includes('duplicate') || 
                err.message?.toLowerCase().includes('already registered') ||
                err.message?.toLowerCase().includes('email already')) {
                setError('An account with this email already exists. Please use a different email or log in.')
                showToast('Email already registered', 'error')
            } else if (err.message?.toLowerCase().includes('password')) {
                setError('Password is too weak. Please use a stronger password.')
                showToast('Weak password', 'error')
            } else {
                setError(err.message || 'Failed to sign up')
                showToast(err.message || 'Failed to sign up', 'error')
            }
        } finally {
            setLoading(false)
        }
    }

    return (
        <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-2xl shadow-lg p-8 max-w-md w-full">
                <div className="text-center mb-8">
                    <div className="text-5xl mb-3">⚽</div>
                    <h1 className="text-3xl font-bold text-gray-800">PredictFC</h1>
                    <p className="text-gray-500 mt-1">Join the prediction community</p>
                </div>

                {error && (
                    <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg mb-4">
                        {error}
                    </div>
                )}

                <form onSubmit={handleSubmit}>
                    <div className="mb-3">
                        <label className="block text-gray-700 font-medium mb-1">Username *</label>
                        <input
                            type="text"
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 bg-white text-gray-800"
                            placeholder="footballfan123"
                            required
                        />
                    </div>

                    <div className="mb-3">
                        <label className="block text-gray-700 font-medium mb-1">Full Name *</label>
                        <input
                            type="text"
                            value={fullName}
                            onChange={(e) => setFullName(e.target.value)}
                            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 bg-white text-gray-800"
                            placeholder="John Doe"
                            required
                        />
                    </div>

                    <div className="mb-3">
                        <label className="block text-gray-700 font-medium mb-1">Email *</label>
                        <input
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 bg-white text-gray-800"
                            placeholder="you@example.com"
                            required
                        />
                    </div>

                    <div className="mb-3">
                        <label className="block text-gray-700 font-medium mb-1">Phone Number</label>
                        <input
                            type="tel"
                            value={phone}
                            onChange={(e) => setPhone(e.target.value)}
                            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 bg-white text-gray-800"
                            placeholder="0821234567"
                        />
                        <p className="text-xs text-gray-400 mt-1">South African number (e.g., 0821234567)</p>
                    </div>

                    <div className="mb-3">
                        <label className="block text-gray-700 font-medium mb-1">Password *</label>
                        <div className="relative">
                            <input
                                type={showPassword ? 'text' : 'password'}
                                value={password}
                                onChange={(e) => {
                                    setPassword(e.target.value)
                                    checkPasswordStrength(e.target.value)
                                }}
                                className="w-full px-4 py-3 pr-12 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-800 bg-white text-gray-800"
                                placeholder="Min 6 characters"
                                required
                                minLength="6"
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                            >
                                {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                            </button>
                        </div>
                        {password && (
                            <div className="mt-2">
                                <div className="w-full h-1.5 bg-gray-200 rounded-full overflow-hidden">
                                    <div 
                                        className="h-full transition-all duration-300 rounded-full"
                                        style={{ 
                                            width: `${(passwordStrength.level / 5) * 100}%`,
                                            background: passwordStrength.color 
                                        }}
                                    />
                                </div>
                                <span className="text-xs text-gray-500 mt-1">
                                    {passwordStrength.text}
                                </span>
                            </div>
                        )}
                        <p className="text-xs text-gray-400 mt-1">At least 6 characters</p>
                    </div>

                    <div className="mb-6">
                        <label className="flex items-center gap-3 cursor-pointer">
                            <input
                                type="checkbox"
                                required
                                className="w-5 h-5 accent-gray-800"
                            />
                            <span className="text-sm text-gray-600">
                                I agree to the <Link to="#" className="text-gray-800 font-semibold hover:underline">Terms of Service</Link> and <Link to="#" className="text-gray-800 font-semibold hover:underline">Privacy Policy</Link>
                            </span>
                        </label>
                    </div>

                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full bg-gray-800 text-white py-3 rounded-lg font-semibold hover:bg-gray-900 transition disabled:opacity-50"
                    >
                        {loading ? 'Creating account...' : 'Create Account'}
                    </button>
                </form>

                <div className="mt-6 pt-6 border-t border-gray-200">
                    <p className="text-center text-gray-500 text-sm">
                        Already have an account?{' '}
                        <Link to="/login" className="text-gray-800 font-semibold hover:underline">
                            Sign In
                        </Link>
                    </p>
                    <p className="text-center text-gray-400 text-xs mt-2">
                        Forgot your password?{' '}
                        <button 
                            onClick={() => navigate('/login')}
                            className="text-gray-500 hover:underline"
                        >
                            Reset it here
                        </button>
                    </p>
                </div>
            </div>
        </div>
    )
}
